{
  "schema_version": "stk_online_llm_v2",
  "recipes": [
    {
      "name": "cheap_frontier_degree",
      "features": [
        {
          "name": "frontier_count",
          "expression": {
            "op": "count",
            "args": [
              {
                "op": "difference",
                "args": [
