      ],
      "rule": "c0 * weight / max(1, 1 + degree) + (c1 * frontier_weight - c2 * frontier_incident_cost) / max(1, frontier_count) - c3 * neighbor_max_weight",
      "patch_policy": {
        "anchor": "blocked_gain",
        "destroy_count": 3,
        "patch_cap": 32,
        "expand_hops": 2,
        "reconstruction": "exchange"
      },
      "evaluation_plan": {
        "feature_scope": "patch",
        "max_feature_cpu_fraction": 0.16,
        "lazy": true
      },
      "adaptation_template": {
        "mutation_scales": [0.1, 0.3, 0.8,
          1.2],
        "stagnation_trials": 16,
        "action": "mutate"
      },
      "coefficients": [1.0, 0.08, 0.025, 0.06],
      "rationale": "The witness's distance-two changed endpoints motivate incident-edge pressure on the exact frontier. This can inspect structural changes missed by unchanged neighbor edge counts and degree sums when those endpoints lie in the legal patch. Frontier weight and size normalize that pressure. Blocked-gain anchoring and three-contact destruction test blocker releases; dynamic ranking precedes the shared improving swaps. Lazy evaluation is confined to 32 nodes, with its scans and invalidations charged. Mutation follows observed feasible gain and CPU, not archived preference fit."
    },
    {
      "name": "resource_compatible_completion",
      "features": [
        {
          "name": "compatible_greedy",
          "expression": {
            "op": "greedy_independent_weight",
            "args": [
              {
                "op": "difference",
                "args": [
                  { "op": "available", "args": [] },
                  {
                    "op": "union",
