      "rule": "c0 * weight / max(1, 1 + degree) - weight * (c1 * frontier_cut_cost + c2 * frontier_internal_cost) / max(1, frontier_weight) - c3 * neighbor_max_weight",
      "patch_policy": {
        "anchor": "rejection_frontier",
        "destroy_count": 8,
        "patch_cap": 64,
        "expand_hops": 2,
        "reconstruction": "rcl"
