        "anchor": "blocked_gain",
        "destroy_count": 10,
        "patch_cap": 48,
        "expand_hops": 2,
        "reconstruction": "exchange"
      },
      "evaluation_plan": {
        "feature_scope": "patch",
        "max_feature_cpu_fraction": 0.25,
        "lazy": true
