      ],
      "rule": "c0 * weight / max(1, 1 + degree) - c1 * two_step_incident_product / max(1, two_step_weight) + c2 * weight * removed_count / max(1, active_count + removed_count) - c3 * neighbor_max_weight",
      "patch_policy": {
        "anchor": "uniform",
        "destroy_count": 12,
        "patch_cap": 32,
        "expand_hops": 1,
        "reconstruction": "greedy"
      },
      "evaluation_plan": {
        "feature_scope": "patch",
        "max_feature_cpu_fraction": 0.18,
        "lazy": true
      },
      "adaptation_template": {
        "mutation_scales": [0.15, 0.45, 1.0,
          1.4],
        "stagnation_trials": 18,
        "action": "switch_recipe"
      },
      "coefficients": [1.0, 0.08, 0.25, 0.02],
      "rationale": "Weighted edge products distinguish conflicts between substantial rewards from equal-count conflicts involving small rewards. Normalization converts the product sum to a seconds-scale pressure. Two-step reachability extends inspection beyond immediate neighbors, while original-domain depletion changes the ranking during reconstruction. Uniform twelve-contact destruction supplies a larger perturbation with a modest 32-node domain and greedy rebuilding. Exact residual queries remain lazy and charged. Switching after prolonged stagnation gives this operator a different search role; its reward and cost must be measured in the complete solve."
    }
